// --- IndexedDB Storage System (MUCHO más espacio que localStorage) ---
const DB_NAME = 'LograrES_DB';
const DB_VERSION = 1;
let db = null;

const Storage = {
    initDB: () => {
        return new Promise((resolve, reject) => {
            if (db) {
                resolve(db);
                return;
            }
            const request = indexedDB.open(DB_NAME, DB_VERSION);

            request.onerror = () => reject(request.error);
            request.onsuccess = () => {
                db = request.result;
                resolve(db);
            };

            request.onupgradeneeded = (event) => {
                const database = event.target.result;
                if (!database.objectStoreNames.contains('patients')) {
                    database.createObjectStore('patients', { keyPath: 'id' });
                }
                if (!database.objectStoreNames.contains('doctors')) {
                    database.createObjectStore('doctors', { keyPath: 'id' });
                }
                if (!database.objectStoreNames.contains('appointments')) {
                    database.createObjectStore('appointments', { keyPath: 'id' });
                }
                if (!database.objectStoreNames.contains('history')) {
                    database.createObjectStore('history', { keyPath: 'id' });
                }
            };
        });
    },

    migrateFromLocalStorage: async () => {
        try {
            await Storage.initDB();
            const keys = ['patients', 'doctors', 'appointments', 'history'];
            for (const key of keys) {
                const raw = localStorage.getItem(key);
                if (raw) {
                    const data = JSON.parse(raw);
                    if (Array.isArray(data) && data.length > 0) {
                        const transaction = db.transaction(key, 'readwrite');
                        const store = transaction.objectStore(key);
                        for (const item of data) {
                            store.put(item);
                        }
                        await new Promise((resolve) => {
                            transaction.oncomplete = resolve;
                        });
                        localStorage.removeItem(key);
                        console.log(`Migrados ${data.length} registros de ${key} a IndexedDB`);
                    }
                }
            }
        } catch (err) {
            console.error('Error migrando de localStorage:', err);
        }
    },

    get: async (key) => {
        try {
            await Storage.initDB();
            return new Promise((resolve, reject) => {
                const transaction = db.transaction(key, 'readonly');
                const store = transaction.objectStore(key);
                const request = store.getAll();
                request.onsuccess = () => resolve(request.result || []);
                request.onerror = () => reject(request.error);
            });
        } catch (err) {
            console.error('Error en Storage.get:', err);
            return [];
        }
    },

    getOne: async (key, id) => {
        try {
            await Storage.initDB();
            return new Promise((resolve, reject) => {
                const transaction = db.transaction(key, 'readonly');
                const store = transaction.objectStore(key);
                const request = store.get(parseInt(id));
                request.onsuccess = () => resolve(request.result || null);
                request.onerror = () => reject(request.error);
            });
        } catch (err) {
            console.error('Error en Storage.getOne:', err);
            return null;
        }
    },

    set: async (key, data) => {
        try {
            await Storage.initDB();
            return new Promise((resolve, reject) => {
                const transaction = db.transaction(key, 'readwrite');
                const store = transaction.objectStore(key);
                store.clear();
                if (Array.isArray(data)) {
                    data.forEach(item => store.put(item));
                }
                transaction.oncomplete = () => resolve();
                transaction.onerror = () => reject(transaction.error);
            });
        } catch (err) {
            console.error('Error en Storage.set:', err);
            throw err;
        }
    },

    add: async (key, item) => {
        try {
            await Storage.initDB();
            const allData = await Storage.get(key);
            const numericIds = allData
                .map(i => Number(i && i.id))
                .filter(n => Number.isFinite(n) && n > 0);
            const nextId = numericIds.length > 0 ? Math.max(...numericIds) + 1 : 1;
            item.id = nextId;

            return new Promise((resolve, reject) => {
                const transaction = db.transaction(key, 'readwrite');
                const store = transaction.objectStore(key);
                const request = store.add(item);
                request.onsuccess = () => resolve(item);
                request.onerror = () => reject(request.error);
            });
        } catch (err) {
            console.error('Error en Storage.add:', err);
            throw err;
        }
    },

    update: async (key, item) => {
        try {
            await Storage.initDB();
            return new Promise((resolve, reject) => {
                const transaction = db.transaction(key, 'readwrite');
                const store = transaction.objectStore(key);
                const request = store.put(item);
                request.onsuccess = () => resolve(true);
                request.onerror = () => reject(request.error);
            });
        } catch (err) {
            console.error('Error en Storage.update:', err);
            throw err;
        }
    },

    delete: async (key, id) => {
        try {
            await Storage.initDB();
            return new Promise((resolve, reject) => {
                const transaction = db.transaction(key, 'readwrite');
                const store = transaction.objectStore(key);
                const request = store.delete(parseInt(id));
                request.onsuccess = () => resolve();
                request.onerror = () => reject(request.error);
            });
        } catch (err) {
            console.error('Error en Storage.delete:', err);
            throw err;
        }
    },
};


document.addEventListener('DOMContentLoaded', async () => {
    // Migrar datos de localStorage a IndexedDB automáticamente
    await Storage.migrateFromLocalStorage();

    setupNavigation();
    setupModals();
    await loadDashboard();
    await loadPatients(); // Cargar pacientes al iniciar la página
    await loadDoctors(); // Cargar profesionales al iniciar la página
    await populateSelects();
    setupMobileMenu();
    setupFilePreviews();
    setupCalendarControls();
    setupNotifications();

    // Revisar turnos próximos cada minuto (Alarma)
    setInterval(checkUpcomingAppointments, 60000);

    // Limpiar formulario de historial al abrirlo como nuevo
    const newHistoryBtn = document.querySelector('button[onclick*="history-modal"]');
    if (newHistoryBtn) {
        newHistoryBtn.addEventListener('click', () => {
            document.getElementById('history-form').reset();
            document.getElementById('h-id').value = '';
            const tratPreview = document.getElementById('h-tratamiento-preview');
            if (tratPreview) tratPreview.textContent = '';
        });
    }
});

function setupMobileMenu() {
    const toggle = document.getElementById('menu-toggle');
    const overlay = document.getElementById('sidebar-overlay');
    if (toggle) { toggle.addEventListener('click', () => { document.body.classList.toggle('sidebar-open'); }); }
    if (overlay) { overlay.addEventListener('click', () => { document.body.classList.remove('sidebar-open'); }); }
}

function setupCalendarControls() {
    document.getElementById('cal-prev')?.addEventListener('click', () => {
        if (CalState.view === 'week') {
            if (!CalState.weekDate) CalState.weekDate = new Date();
            CalState.weekDate.setDate(CalState.weekDate.getDate() - 7);
            CalState.month = CalState.weekDate.getMonth();
            CalState.year = CalState.weekDate.getFullYear();
        } else {
            CalState.month--;
            if (CalState.month < 0) { CalState.month = 11; CalState.year--; }
        }
        renderCalendar();
    });
    document.getElementById('cal-next')?.addEventListener('click', () => {
        if (CalState.view === 'week') {
            if (!CalState.weekDate) CalState.weekDate = new Date();
            CalState.weekDate.setDate(CalState.weekDate.getDate() + 7);
            CalState.month = CalState.weekDate.getMonth();
            CalState.year = CalState.weekDate.getFullYear();
        } else {
            CalState.month++;
            if (CalState.month > 11) { CalState.month = 0; CalState.year++; }
        }
        renderCalendar();
    });
    document.getElementById('cal-today')?.addEventListener('click', () => {
        const now = new Date();
        CalState.year = now.getFullYear();
        CalState.month = now.getMonth();
        CalState.weekDate = new Date(now);
        renderCalendar();
    });
    document.querySelectorAll('.cal-tab').forEach(tab => {
        tab.addEventListener('click', () => {
            document.querySelectorAll('.cal-tab').forEach(t => t.classList.remove('active'));
            tab.classList.add('active');
            CalState.view = tab.dataset.view;
            if (CalState.view === 'week') {
                // Si no hay una fecha de semana sincronizada, usa hoy o el mes actual
                if (!CalState.weekDate) {
                    const now = new Date();
                    if (CalState.year === now.getFullYear() && CalState.month === now.getMonth()) {
                        CalState.weekDate = new Date(now);
                    } else {
                        // Usar el 15 del mes (usualmente en la segunda semana) para asegurar que se muestren turnos de todo el mes
                        CalState.weekDate = new Date(CalState.year, CalState.month, 15);
                    }
                } else if (CalState.month !== CalState.weekDate.getMonth() || CalState.year !== CalState.weekDate.getFullYear()) {
                    // Si la fecha guardada no coincide con el mes/año actual, reajustar
                    CalState.weekDate = new Date(CalState.year, CalState.month, 15);
                }
            }
            document.querySelectorAll('.cal-view').forEach(v => v.classList.remove('active'));
            document.getElementById(`cal-view-${CalState.view}`)?.classList.add('active');
            document.getElementById('cal-day-panel').style.display = 'none';
            CalState.selectedDate = null;
            renderCalendar();
        });
    });
}

// --- Sistema de Notificaciones (Alarma) ---
function setupNotifications() {
    if (!("Notification" in window)) return;
    if (Notification.permission !== "granted" && Notification.permission !== "denied") {
        Notification.requestPermission();
    }
}

async function checkUpcomingAppointments() {
    if (Notification.permission !== "granted") return;

    const allApps = await Storage.get('appointments');
    const patients = await Storage.get('patients');
    const now = new Date();
    const todayStr = now.toISOString().split('T')[0];

    // Ya avisados en esta sesión para no repetir
    const notified = JSON.parse(sessionStorage.getItem('notified_appointments') || '[]');

    allApps.forEach(a => {
        if (a.date === todayStr && (a.status || 'Pendiente') === 'Pendiente' && !notified.includes(a.id)) {
            const [hh, mm] = a.time.split(':').map(Number);
            const appTime = new Date();
            appTime.setHours(hh, mm, 0);

            const diffMs = appTime - now;
            const diffMin = Math.round(diffMs / 60000);

            // Avisar si faltan entre 1 y 15 minutos
            if (diffMin > 0 && diffMin <= 15) {
                const p = patients.find(x => x.id == a.patientId) || { name: 'Paciente', lastname: '' };
                const n = new Notification("Próximo Turno: LograrES", {
                    body: `En ${diffMin} min: ${p.name} ${p.lastname} a las ${a.time}`,
                    icon: 'https://cdn-icons-png.flaticon.com/512/1048/1048953.png'
                });

                // Sonido de alerta
                const audio = new Audio('https://assets.mixkit.co/active_storage/sfx/2869/2869-preview.mp3');
                audio.play().catch(() => { });

                notified.push(a.id);
                sessionStorage.setItem('notified_appointments', JSON.stringify(notified));
            }
        }
    });
}

// --- Envío de WhatsApp ---
window.sendWhatsAppReminder = async function (id) {
    const allApps = await Storage.get('appointments');
    const a = allApps.find(x => x.id == id);
    if (!a) return;
    const allPatients = await Storage.get('patients');
    const p = allPatients.find(x => x.id == a.patientId);
    if (!p || !p.phone) {
        alert("El paciente no tiene un número de teléfono registrado.");
        return;
    }

    const message = `Hola ${p.name}, te recordamos tu turno en LograrES para hoy a las ${a.time}. ¡Te esperamos!`;
    const encodedMsg = encodeURIComponent(message);
    const phone = p.phone.replace(/\D/g, ''); // Limpiar el número

    window.open(`https://wa.me/${phone}?text=${encodedMsg}`, '_blank');
};

function setupNavigation() {
    const links = document.querySelectorAll('.nav-link');
    const sections = document.querySelectorAll('.view-section');

    links.forEach(link => {
        link.addEventListener('click', (e) => {
            e.preventDefault();
            const targetId = link.getAttribute('data-target');
            const titleMap = {
                'dashboard': 'Dashboard',
                'patients': 'Gestión de Pacientes',
                'appointments': 'Turnos Programados',
                'history': 'Historial Clínico',
                'settings': 'Configuración'
            };
            document.getElementById('page-title').innerText = titleMap[targetId];
            links.forEach(l => l.classList.remove('active'));
            link.classList.add('active');
            sections.forEach(s => s.classList.remove('active'));
            document.getElementById(targetId).classList.add('active');

            if (targetId === 'dashboard') loadDashboard();
            if (targetId === 'patients') loadPatients();
            if (targetId === 'appointments') { loadAppointments(); populateSelects(); }
            if (targetId === 'history') { populateSelects(); searchHistory(); }

            if (window.innerWidth <= 768) {
                document.body.classList.remove('sidebar-open');
            }
        });
    });
}

function openModal(modalId) {
    document.getElementById(modalId).classList.add('active');
    return populateSelects();
}

function closeModal(modalId) {
    document.getElementById(modalId).classList.remove('active');
}

window.openNewPatientModal = function () {
    const form = document.getElementById('patient-form');
    if (form) form.reset();
    const pid = document.getElementById('p-id');
    if (pid) pid.value = '';
    openModal('patient-modal');
};

window.openNewAppointmentModal = function () {
    const form = document.getElementById('appointment-form');
    if (form) form.reset();
    const aid = document.getElementById('a-id');
    if (aid) aid.value = '';
    const title = document.getElementById('appointment-modal-title');
    if (title) title.textContent = 'Nuevo Turno';

    const patientSearch = document.getElementById('a-patient-search');
    if (patientSearch) patientSearch.value = '';
    const results = document.getElementById('a-patient-results');
    if (results) { results.innerHTML = ''; results.style.display = 'none'; }

    openModal('appointment-modal');

    if (typeof window.filterAppointmentPatients === 'function') {
        window.filterAppointmentPatients();
    }
};

window.openNewHistoryModal = function () {
    const form = document.getElementById('history-form');
    if (form) form.reset();
    const hid = document.getElementById('h-id');
    if (hid) hid.value = '';
    const title = document.getElementById('history-modal-title');
    if (title) title.textContent = 'Nuevo Historial';
    const tratPreview = document.getElementById('h-tratamiento-preview');
    if (tratPreview) tratPreview.textContent = '';
    openModal('history-modal');
};

function _escapeHtml(str) {
    return (str || '').toString()
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#039;');
}

function _renderAppointmentPatientResults(patients) {
    const results = document.getElementById('a-patient-results');
    if (!results) return;

    if (!patients || patients.length === 0) {
        results.innerHTML = '';
        results.style.display = 'none';
        return;
    }

    const max = 8;
    const items = patients.slice(0, max);
    results.innerHTML = items.map(p => {
        const phone = p.phone ? ` - ${_escapeHtml(p.phone)}` : '';
        const label = `${_escapeHtml(p.name || '')} ${_escapeHtml(p.lastname || '')}${phone}`.trim();
        return `<div class="select-result-item" onclick="selectAppointmentPatient('${_escapeHtml(p.id)}')">${label}</div>`;
    }).join('');
    results.style.display = 'block';
}

window.selectAppointmentPatient = function (id) {
    const sel = document.getElementById('a-patient');
    if (sel) sel.value = id;
    const results = document.getElementById('a-patient-results');
    if (results) { results.innerHTML = ''; results.style.display = 'none'; }
};

window.filterAppointmentPatients = async function () {
    const input = document.getElementById('a-patient-search');
    const select = document.getElementById('a-patient');
    if (!select) return;

    const currentValue = select.value;
    const q = (input ? input.value : '').trim().toLowerCase();

    const patients = await Storage.get('patients');
    const filtered = q
        ? patients.filter(p =>
            (p.name && p.name.toLowerCase().includes(q)) ||
            (p.lastname && p.lastname.toLowerCase().includes(q)) ||
            (p.phone && p.phone.toLowerCase().includes(q))
        )
        : patients;

    _renderAppointmentPatientResults(q ? filtered : []);

    select.innerHTML = '<option value="">Seleccione Paciente</option>';
    filtered.forEach(p => {
        const phoneLabel = p.phone ? ` - ${p.phone}` : '';
        select.innerHTML += `<option value="${p.id}">${p.name} ${p.lastname}${phoneLabel}</option>`;
    });

    if (currentValue && Array.from(select.options).some(o => o.value === currentValue)) {
        select.value = currentValue;
    }
};

function setupModals() {
    window.onclick = (e) => {
        if (e.target.classList.contains('modal')) {
            e.target.classList.remove('active');
        }
    };
}

async function loadDashboard() {
    const p = await Storage.get('patients');
    const a = await Storage.get('appointments');
    const h = await Storage.get('history');
    const today = new Date().toISOString().split('T')[0];
    const todayApps = a.filter(item => item.date === today && (item.status || 'Pendiente') === 'Pendiente');

    document.getElementById('total-patients').innerText = p.length;
    document.getElementById('today-appointments').innerText = todayApps.length;
    document.getElementById('total-history').innerText = h.length;
}

// --- Gestión de Pacientes ---
const patientForm = document.getElementById('patient-form');
if (patientForm) {
    patientForm.addEventListener('submit', async (e) => {
        e.preventDefault();
        console.log('Evento submit del formulario de pacientes activado');
        try {
            const id = document.getElementById('p-id').value;
            console.log('ID del paciente:', id);

            const docInput = document.getElementById('p-documentacion');
            let documentacionData = null;
            let documentacionName = null;
            if (docInput && docInput.files[0]) {
                documentacionName = docInput.files[0].name;
                documentacionData = await readFileAsDataURL(docInput);
            } else if (id) {
                const allPatients = await Storage.get('patients');
                const existing = allPatients.find(i => i.id == id);
                if (existing) {
                    documentacionData = existing.documentacionData || null;
                    documentacionName = existing.documentacionName || null;
                }
            }

            const patientData = {
                name: document.getElementById('p-name').value,
                lastname: document.getElementById('p-lastname').value,
                dob: document.getElementById('p-dob').value,
                phone: document.getElementById('p-phone').value,
                email: document.getElementById('p-email').value,
                documentacionData,
                documentacionName
            };

            console.log('Datos del paciente:', patientData);
            if (id) {
                patientData.id = parseInt(id);
                await Storage.update('patients', patientData);
                console.log('Paciente actualizado:', patientData);
            } else {
                await Storage.add('patients', patientData);
                console.log('Paciente agregado:', patientData);
            }
            console.log('Contenido en IndexedDB de pacientes:', await Storage.get('patients'));

            closeModal('patient-modal');
            patientForm.reset();
            document.getElementById('p-doc-preview').textContent = '';
            await loadPatients();
            await loadDashboard();
            alert('✅ Paciente guardado correctamente');
        } catch (err) {
            console.error('Error al guardar paciente:', err);
            alert('❌ Error al guardar paciente. Por favor, intentá nuevamente.');
        }
    });
} else {
    console.error('No se encontró el formulario de pacientes'); // Registro si el formulario no existe
}

window.editPatient = async function (id) {
    console.log('Editando paciente con ID:', id);
    const allPatients = await Storage.get('patients');
    const p = allPatients.find(i => i.id == id);
    if (!p) {
        console.error('Paciente no encontrado');
        return;
    }
    document.getElementById('p-id').value = p.id;
    document.getElementById('p-name').value = p.name;
    document.getElementById('p-lastname').value = p.lastname;
    document.getElementById('p-dob').value = p.dob;
    document.getElementById('p-phone').value = p.phone;
    document.getElementById('p-email').value = p.email || '';
    const preview = document.getElementById('p-doc-preview');
    if (preview) {
        preview.textContent = p.documentacionName ? `📄 ${p.documentacionName}` : '';
    }
    console.log('Datos cargados en el formulario:', p);
    openModal('patient-modal');
};

async function loadPatients() {
    const allPatients = await Storage.get('patients');
    const searchInput = document.getElementById('patient-search');
    const q = searchInput ? searchInput.value.trim().toLowerCase() : '';
    const patients = q
        ? allPatients.filter(p =>
            (p.name && p.name.toLowerCase().includes(q)) ||
            (p.lastname && p.lastname.toLowerCase().includes(q)) ||
            (p.phone && p.phone.toLowerCase().includes(q))
        )
        : allPatients;

    const tbody = document.getElementById('patients-table-body');
    if (!tbody) return;
    tbody.innerHTML = '';

    if (patients.length === 0) {
        tbody.innerHTML = `<tr><td colspan="6" style="text-align:center; color:#888; padding:30px;">
            <i class='bx bx-search' style="font-size:2rem; display:block; margin-bottom:8px;"></i>
            No se encontraron pacientes${q ? ` para "<strong>${q}</strong>"` : ''}.
        </td></tr>`;
        return;
    }

    patients.forEach(p => {
        const age = new Date().getFullYear() - new Date(p.dob).getFullYear();
        const docIcon = adjuntoIcon('patients', p.id, p.documentacionName, 'documentacionData');
        tbody.innerHTML += `
            <tr>
                <td>#${p.id}</td>
                <td>${p.name} ${docIcon}</td>
                <td>${p.lastname}</td>
                <td>${age} años</td>
                <td>${p.phone}</td>
                <td>
                    <button class="btn-secondary" onclick="editPatient(${p.id})" style="padding:5px 10px; font-size:12px;">Editar</button>
                    <button class="btn-secondary" onclick="deletePatient(${p.id})" style="background:#e74c3c; padding:5px 10px; font-size:12px; margin-left:5px;">Eliminar</button>
                </td>
            </tr>
        `;
    });
}


window.deletePatient = async function (id) {
    if (confirm('¿Eliminar paciente?')) {
        await Storage.delete('patients', id);
        await loadPatients();
        await loadDashboard();
    }
};

async function populateSelects() {
    const patients = await Storage.get('patients');
    const doctors = await Storage.get('doctors');

    // Conserva la selección actual (al editar se cargan los datos antes de abrir el modal)
    function _keepSelection(sel, prevValue) {
        if (prevValue && Array.from(sel.options).some(o => o.value === prevValue)) {
            sel.value = prevValue;
        } else {
            sel.value = '';
        }
    }

    ['a-patient', 'h-patient'].forEach(id => {
        const sel = document.getElementById(id);
        if (sel) {
            const prev = sel.value;
            sel.innerHTML = '<option value="">Seleccione Paciente</option>';
            patients.forEach(p => {
                const phoneLabel = p.phone ? ` - ${p.phone}` : '';
                sel.innerHTML += `<option value="${p.id}">${p.name} ${p.lastname}${phoneLabel}</option>`;
            });
            _keepSelection(sel, prev);
        }
    });

    // Llenar selector de profesionales para turnos y historial
    ['a-doctor', 'h-professional'].forEach(id => {
        const doctorSelect = document.getElementById(id);
        if (doctorSelect) {
            const prev = doctorSelect.value;
            doctorSelect.innerHTML = '<option value="">Seleccione Profesional</option>';
            doctors.forEach(d => {
                doctorSelect.innerHTML += `<option value="${d.id}">${d.name} ${d.lastname} - ${d.specialty}</option>`;
            });
            _keepSelection(doctorSelect, prev);
        }
    });

    if (typeof window.filterAppointmentPatients === 'function') {
        window.filterAppointmentPatients();
    }
}


// --- Gestión de Turnos — Vista Calendario ---
const CalState = {
    year: new Date().getFullYear(),
    month: new Date().getMonth(),
    view: 'month',
    selectedDate: null,
};

const MONTHS_ES = ['Enero', 'Febrero', 'Marzo', 'Abril', 'Mayo', 'Junio',
    'Julio', 'Agosto', 'Septiembre', 'Octubre', 'Noviembre', 'Diciembre'];
const DAYS_SHORT_ES = ['Dom', 'Lun', 'Mar', 'Mié', 'Jue', 'Vie', 'Sáb'];

function statusClass(status) {
    if (status === 'Asistió') return 'status-asistio';
    if (status === 'Cancelado') return 'status-cancelado';
    return 'status-pendiente';
}

function formatDateES(dateStr) {
    if (!dateStr) return '';
    const [y, m, d] = dateStr.split('-');
    const dt = new Date(parseInt(y), parseInt(m) - 1, parseInt(d));
    return `${DAYS_SHORT_ES[dt.getDay()]} ${parseInt(d)} de ${MONTHS_ES[parseInt(m) - 1]} ${y}`;
}

async function getAppointmentsForDate(dateStr) {
    const allApps = await Storage.get('appointments');
    const patients = await Storage.get('patients');
    return allApps
        .filter(a => a.date === dateStr)
        .sort((a, b) => (a.time || '').localeCompare(b.time || ''))
        .map(a => {
            const p = patients.find(x => x.id == a.patientId) || { name: 'Desconocido', lastname: '' };
            return { ...a, patientName: `${p.name} ${p.lastname}` };
        });
}

async function renderCalendar() {
    const label = document.getElementById('cal-month-label');
    if (label && CalState.view !== 'week') {
        label.textContent = `${MONTHS_ES[CalState.month]} ${CalState.year}`;
    }
    if (CalState.view === 'month') await renderMonthView();
    else if (CalState.view === 'week') await renderWeekView();
    else if (CalState.view === 'list') await renderListView();
}

async function renderMonthView() {
    const grid = document.getElementById('cal-grid');
    if (!grid) return;
    grid.innerHTML = '';
    const today = new Date();
    const todayStr = today.toISOString().split('T')[0];
    const firstDay = new Date(CalState.year, CalState.month, 1).getDay();
    const daysInMonth = new Date(CalState.year, CalState.month + 1, 0).getDate();
    const prevDays = new Date(CalState.year, CalState.month, 0).getDate();
    const allApps = await Storage.get('appointments');
    const patients = await Storage.get('patients');
    const appsMap = {};
    allApps.forEach(a => {
        if (!appsMap[a.date]) appsMap[a.date] = [];
        const p = patients.find(x => x.id == a.patientId) || { name: '?', lastname: '' };
        appsMap[a.date].push({ ...a, patientName: `${p.name} ${p.lastname}` });
    });
    const totalCells = Math.ceil((firstDay + daysInMonth) / 7) * 7;
    for (let i = 0; i < totalCells; i++) {
        const cell = document.createElement('div');
        cell.className = 'cal-cell';
        let dayNum, month, year, isOther = false;
        if (i < firstDay) {
            dayNum = prevDays - firstDay + 1 + i; month = CalState.month - 1; year = CalState.year;
            if (month < 0) { month = 11; year--; } isOther = true;
        } else if (i >= firstDay + daysInMonth) {
            dayNum = i - firstDay - daysInMonth + 1; month = CalState.month + 1; year = CalState.year;
            if (month > 11) { month = 0; year++; } isOther = true;
        } else { dayNum = i - firstDay + 1; month = CalState.month; year = CalState.year; }
        const mm = String(month + 1).padStart(2, '0');
        const dd = String(dayNum).padStart(2, '0');
        const dateStr = `${year}-${mm}-${dd}`;
        if (isOther) cell.classList.add('cal-other-month');
        if (dateStr === todayStr) cell.classList.add('cal-today');
        if (dateStr === CalState.selectedDate) cell.classList.add('cal-selected');
        const numEl = document.createElement('div');
        numEl.className = 'cal-day-num';
        numEl.textContent = dayNum;
        cell.appendChild(numEl);
        const dayApps = (appsMap[dateStr] || []).sort((a, b) => (a.time || '').localeCompare(b.time || ''));
        const maxVisible = 2;
        dayApps.slice(0, maxVisible).forEach(a => {
            const ev = document.createElement('div');
            ev.className = `cal-event ${statusClass(a.status || 'Pendiente')}`;
            ev.innerHTML = `<span class="cal-event-dot"></span>${a.time || ''} ${a.patientName}`;
            ev.onclick = (e) => { e.stopPropagation(); openDayPanel(dateStr); };
            cell.appendChild(ev);
        });
        if (dayApps.length > maxVisible) {
            const more = document.createElement('div');
            more.className = 'cal-more';
            more.textContent = `+${dayApps.length - maxVisible} más`;
            more.onclick = (e) => { e.stopPropagation(); openDayPanel(dateStr); };
            cell.appendChild(more);
        }
        cell.onclick = () => openDayPanel(dateStr);
        grid.appendChild(cell);
    }
}

async function renderWeekView() {
    const container = document.getElementById('cal-week-container');
    if (!container) return;
    if (!CalState.weekDate) {
        CalState.weekDate = new Date();
    }
    const today = new Date();
    const ref = new Date(CalState.weekDate);
    const startOfWeek = new Date(ref);
    startOfWeek.setDate(ref.getDate() - ref.getDay());

    // Configurar el título superior para mostrar el rango de la semana
    const label = document.getElementById('cal-month-label');
    if (label) {
        const endOfWeek = new Date(startOfWeek);
        endOfWeek.setDate(startOfWeek.getDate() + 6);
        if (startOfWeek.getMonth() === endOfWeek.getMonth()) {
            label.textContent = `Semana ${startOfWeek.getDate()} al ${endOfWeek.getDate()} de ${MONTHS_ES[startOfWeek.getMonth()]}`;
        } else {
            label.textContent = `Sem ${startOfWeek.getDate()} ${MONTHS_ES[startOfWeek.getMonth()]} al ${endOfWeek.getDate()} ${MONTHS_ES[endOfWeek.getMonth()]}`;
        }
    }

    const todayStr = `${today.getFullYear()}-${String(today.getMonth() + 1).padStart(2, '0')}-${String(today.getDate()).padStart(2, '0')}`;
    let headerHTML = `<div class="cal-week-day-header"><div class="cal-week-day-col"></div>`;
    const weekDates = [];
    for (let d = 0; d < 7; d++) {
        const dt = new Date(startOfWeek);
        dt.setDate(startOfWeek.getDate() + d);
        const ds = `${dt.getFullYear()}-${String(dt.getMonth() + 1).padStart(2, '0')}-${String(dt.getDate()).padStart(2, '0')}`;
        weekDates.push(ds);
        const isToday = ds === todayStr;
        headerHTML += `<div class="cal-week-day-col${isToday ? ' cal-today-col' : ''}">
            ${DAYS_SHORT_ES[dt.getDay()]}<br><strong>${dt.getDate()}</strong></div>`;
    }
    headerHTML += `</div>`;
    const hours = [];
    for (let h = 7; h <= 20; h++) hours.push(h);
    let timeSlotsHTML = '';
    hours.forEach(h => { timeSlotsHTML += `<div class="cal-week-time-slot">${String(h).padStart(2, '0')}:00</div>`; });
    const allApps = await Storage.get('appointments');
    const patients = await Storage.get('patients');
    let dayColsHTML = weekDates.map(ds => {
        const dayApps = allApps.filter(a => a.date === ds);
        let eventsHTML = '';
        for (let h = 0; h < hours.length; h++) {
            eventsHTML += `<div style="height:54px; border-bottom:1px solid #f0f0f0;"></div>`;
        }
        dayApps.forEach(a => {
            const p = patients.find(x => x.id == a.patientId) || { name: '?', lastname: '' };
            const [hh, mm] = (a.time || '08:00').split(':').map(Number);
            const topOffset = ((hh - 7) * 54) + (mm / 60 * 54);
            const status = a.status || 'Pendiente';
            const bgColor = status === 'Asistió' ? '#27ae60' : (status === 'Cancelado' ? '#e74c3c' : '#f39c12');
            eventsHTML += `<div class="cal-week-event" style="top:${topOffset}px; height:48px; background:${bgColor}20; color:${bgColor}; border-left:3px solid ${bgColor};"
                onclick="openDayPanel('${ds}')">${a.time} ${p.name}</div>`;
        });
        return `<div class="cal-week-day-events" style="position:relative; min-height:${hours.length * 54}px;">${eventsHTML}</div>`;
    }).join('');
    container.innerHTML = `${headerHTML}<div class="cal-week-body"><div class="cal-week-time-col">${timeSlotsHTML}</div>${dayColsHTML}</div>`;
}

async function renderListView() {
    const body = document.getElementById('cal-list-body');
    if (!body) return;
    const allApps = await Storage.get('appointments');
    const patients = await Storage.get('patients');
    const q = (document.getElementById('appointment-search') || {}).value?.trim().toLowerCase() || '';
    const statusQ = (document.getElementById('appointment-status-filter') || {}).value || '';
    let apps = allApps
        .map(a => {
            const p = patients.find(x => x.id == a.patientId) || { name: 'Desconocido', lastname: '' };
            return { ...a, patientName: `${p.name} ${p.lastname}` };
        })
        .filter(a => {
            const matchText = !q || a.patientName.toLowerCase().includes(q) || (a.date || '').includes(q);
            const matchStatus = !statusQ || (a.status || 'Pendiente') === statusQ;
            return matchText && matchStatus;
        })
        .sort((a, b) => { const ds = (a.date || '').localeCompare(b.date || ''); return ds !== 0 ? ds : (a.time || '').localeCompare(b.time || ''); });
    if (apps.length === 0) {
        body.innerHTML = `<div class="cal-list-empty"><i class='bx bx-calendar-x'></i>No hay turnos${q ? ` para "<strong>${q}</strong>"` : ''}${statusQ ? ` con estado "${statusQ}"` : ''}</div>`;
        return;
    }
    const groups = {};
    apps.forEach(a => { if (!groups[a.date]) groups[a.date] = []; groups[a.date].push(a); });
    body.innerHTML = Object.keys(groups).sort().map(date => {
        const label = formatDateES(date);
        const items = groups[date].map(a => {
            const status = a.status || 'Pendiente';
            const sc = statusClass(status);
            const actionsPending = status === 'Pendiente'
                ? `<button title="Asistió" onclick="calMarkAttended(${a.id})"><i class='bx bx-check'></i></button>
                   <button title="Cancelar" onclick="calCancel(${a.id})" style="color:#e74c3c;"><i class='bx bx-x'></i></button>`
                : `<button title="Reabrir" onclick="calReopen(${a.id})"><i class='bx bx-revision'></i></button>`;
            return `<div class="cal-list-item">
                <div class="cal-list-status-bar ${sc}"></div>
                <div class="cal-list-info">
                    <div class="cal-list-time"><i class='bx bx-time-five'></i> ${a.time || '--:--'}</div>
                    <div class="cal-list-patient">${a.patientName}</div>
                    ${a.notes ? `<div class="cal-list-notes">${a.notes}</div>` : ''}
                </div>
                <span class="cal-list-badge ${sc}">${status}</span>
                <div class="cal-list-actions">
                    <button title="WhatsApp" onclick="sendWhatsAppReminder(${a.id})" style="color:#27ae60;"><i class='bx bxl-whatsapp'></i></button>
                    <button title="Editar" onclick="calEdit(${a.id})"><i class='bx bxs-edit'></i></button>
                    ${actionsPending}
                    <button title="Eliminar" onclick="calDelete(${a.id})" style="color:#e74c3c;"><i class='bx bxs-trash'></i></button>
                </div>
            </div>`;
        }).join('');
        return `<div class="cal-list-group"><div class="cal-list-date-label">${label}</div>${items}</div>`;
    }).join('');
}

let _selectedDayForNew = null;

async function openDayPanel(dateStr) {
    CalState.selectedDate = dateStr;
    _selectedDayForNew = dateStr;
    await renderCalendar();
    const panel = document.getElementById('cal-day-panel');
    const title = document.getElementById('cal-day-panel-title');
    const panelBody = document.getElementById('cal-day-panel-body');
    if (!panel) return;
    title.textContent = formatDateES(dateStr);
    const apps = await getAppointmentsForDate(dateStr);
    if (apps.length === 0) {
        panelBody.innerHTML = `<div class="cal-panel-empty"><i class='bx bx-calendar' style="font-size:2rem; display:block; margin-bottom:6px;"></i>Sin turnos este día</div>`;
    } else {
        panelBody.innerHTML = apps.map(a => {
            const status = a.status || 'Pendiente';
            const sc = statusClass(status);
            return `<div class="cal-panel-item ${sc}">
                <div class="cal-panel-time">${a.time || '--:--'}</div>
                <div class="cal-panel-patient">${a.patientName}</div>
                <div class="cal-panel-status">${status}</div>
                <div class="cal-panel-actions">
                    <button onclick="calEdit(${a.id})"><i class='bx bxs-edit'></i></button>
                    <button onclick="calDelete(${a.id})" style="color:#e74c3c;"><i class='bx bxs-trash'></i></button>
                </div>
            </div>`;
        }).join('');
    }
    panel.style.display = 'block';
}

async function closeDayPanel() {
    CalState.selectedDate = null;
    _selectedDayForNew = null;
    document.getElementById('cal-day-panel').style.display = 'none';
    await renderCalendar();
}

window.openNewTurnoForDay = async function () {
    if (!_selectedDayForNew) return;
    openNewAppointmentModal();
    document.getElementById('a-date').value = _selectedDayForNew;
};

async function openNewAppointmentModal() {
    document.getElementById('appointment-form').reset();
    document.getElementById('a-id').value = '';
    document.getElementById('appointment-modal-title').textContent = 'Nuevo Turno';
    CalState.selectedDate = null;
    _selectedDayForNew = null;
    document.getElementById('cal-day-panel').style.display = 'none';
    await renderCalendar();
    const results = document.getElementById('a-patient-results');
    if (results) { results.innerHTML = ''; results.style.display = 'none'; }

    openModal('appointment-modal');

    if (typeof window.filterAppointmentPatients === 'function') {
        await window.filterAppointmentPatients();
    }
};

window.calMarkAttended = async function (id) {
    const allApps = await Storage.get('appointments');
    const a = allApps.find(x => x.id == id);
    if (!a) return;
    a.status = 'Asistió';
    await Storage.update('appointments', a);
    await loadDashboard(); await renderCalendar();
    if (CalState.selectedDate) openDayPanel(CalState.selectedDate);
};
window.calCancel = async function (id) {
    if (!confirm('¿Cancelar este turno?')) return;
    const allApps = await Storage.get('appointments');
    const a = allApps.find(x => x.id == id);
    if (!a) return;
    a.status = 'Cancelado';
    await Storage.update('appointments', a);
    await loadDashboard(); await renderCalendar();
    if (CalState.selectedDate) openDayPanel(CalState.selectedDate);
};
window.calReopen = async function (id) {
    const allApps = await Storage.get('appointments');
    const a = allApps.find(x => x.id == id);
    if (!a) return;
    a.status = 'Pendiente';
    await Storage.update('appointments', a);
    await loadDashboard(); await renderCalendar();
    if (CalState.selectedDate) openDayPanel(CalState.selectedDate);
};
window.calEdit = async function (id) {
    const allApps = await Storage.get('appointments');
    const a = allApps.find(x => x.id == id);
    if (!a) return;

    const patientSearch = document.getElementById('a-patient-search');
    if (patientSearch) patientSearch.value = '';
    const results = document.getElementById('a-patient-results');
    if (results) { results.innerHTML = ''; results.style.display = 'none'; }

    document.getElementById('a-id').value = a.id;
    document.getElementById('a-patient').value = a.patientId;
    document.getElementById('a-date').value = a.date;
    document.getElementById('a-time').value = a.time;
    document.getElementById('a-notes').value = a.notes || '';
    document.getElementById('appointment-modal-title').textContent = 'Editar Turno';
    openModal('appointment-modal');

    if (typeof window.filterAppointmentPatients === 'function') {
        window.filterAppointmentPatients();
    }
};
window.calDelete = async function (id) {
    if (!confirm('¿Eliminar este turno?')) return;
    await Storage.delete('appointments', id);
    await loadDashboard(); await renderCalendar();
    if (CalState.selectedDate) openDayPanel(CalState.selectedDate);
};

window.editAppointment = window.calEdit;
window.deleteAppointment = window.calDelete;
window.markAppointmentAsAttended = window.calMarkAttended;
window.cancelAppointment = window.calCancel;
window.reopenAppointment = window.calReopen;

const appForm = document.getElementById('appointment-form');
if (appForm) {
    appForm.addEventListener('submit', async (e) => {
        e.preventDefault();
        try {
            const id = document.getElementById('a-id').value;
            const patientId = document.getElementById('a-patient').value;
            const date = document.getElementById('a-date').value;
            const time = document.getElementById('a-time').value;
            const notes = document.getElementById('a-notes').value;

            // Validar turno duplicado (evitar doble reserva)
            const allAppointments = await Storage.get('appointments');
            const isDuplicate = allAppointments.some(a =>
                a.date === date &&
                a.time === time &&
                a.status !== 'Cancelado' &&
                a.id != id // Permite editar el mismo turno sin saltar el error
            );

            if (isDuplicate) {
                alert(`⚠️ ¡ATENCIÓN! Ya existe un turno programado para el día ${date} a las ${time}.\n\nPor favor, revisa el calendario y elige otro horario para evitar sobreposiciones.`);
                return; // Detenemos el guardado
            }

            if (id) {
                const allApps = await Storage.get('appointments');
                const current = allApps.find(a => a.id == id);
                if (!current) throw new Error('Turno no encontrado');
                current.patientId = patientId; current.date = date; current.time = time; current.notes = notes;
                await Storage.update('appointments', current);
            } else {
                await Storage.add('appointments', { patientId, date, time, notes, status: 'Pendiente' });
            }
            closeModal('appointment-modal');
            appForm.reset();
            document.getElementById('a-id').value = '';
            document.getElementById('appointment-modal-title').textContent = 'Nuevo Turno';
            await loadDashboard(); await renderCalendar();
            if (CalState.selectedDate) openDayPanel(CalState.selectedDate);
        } catch (err) {
            alert(`❌ No se pudo agendar el turno.\n${err && err.message ? err.message : err}`);
        }
    });
}

async function loadAppointments() { await renderCalendar(); }



// --- Utilidad para lectura de archivos ---
async function readFileAsDataURL(input) {
    if (!input || !input.files || !input.files[0]) return null;
    return new Promise((resolve) => {
        const reader = new FileReader();
        reader.onload = (e) => resolve(e.target.result);
        reader.readAsDataURL(input.files[0]);
    });
}

// --- Iconos de adjuntos (PDF / Word) en las tablas ---
function _escAttr(v) {
    return String(v === null || v === undefined ? '' : v)
        .replace(/&/g, '&amp;')
        .replace(/"/g, '&quot;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;');
}

function adjuntoIcon(store, id, name, field) {
    if (!name) return '';
    return `<a href="#" data-adjunto-store="${_escAttr(store)}" data-adjunto-id="${_escAttr(id)}" data-adjunto-field="${_escAttr(field)}" data-adjunto-name="${_escAttr(name)}" title="${_escAttr(name)} — clic para descargar" style="text-decoration:none; margin-right:5px; font-size:16px;">📄</a>`;
}

document.addEventListener('click', async function (e) {
    const link = e.target && e.target.closest ? e.target.closest('a[data-adjunto-store]') : null;
    if (!link) return;
    e.preventDefault();

    const store = link.getAttribute('data-adjunto-store');
    const id = link.getAttribute('data-adjunto-id');
    const field = link.getAttribute('data-adjunto-field');
    const name = link.getAttribute('data-adjunto-name') || 'archivo';

    try {
        const all = await Storage.get(store);
        const rec = all.find(r => String(r && r.id) === String(id));
        const data = rec ? rec[field] : null;

        if (!data) {
            alert('📄 ' + name + '\n\nEste archivo se guardó únicamente con su nombre: el documento original está guardado en la carpeta de esta PC.\n\nBuscá el archivo con ese nombre en tu computadora y abrilo desde ahí.');
            return;
        }

        const a = document.createElement('a');
        a.href = data;
        a.download = name;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
    } catch (err) {
        console.error('Error al descargar adjunto:', err);
        alert('❌ No se pudo descargar el archivo.');
    }
});

function setupFilePreviews() {
    const docInput = document.getElementById('p-documentacion');
    if (docInput) {
        docInput.addEventListener('change', (e) => {
            const file = e.target.files[0];
            const preview = document.getElementById('p-doc-preview');
            if (file && preview) {
                preview.textContent = `📄 ${file.name}`;
            } else if (preview) {
                preview.textContent = '';
            }
        });
    }
    const tratInput = document.getElementById('h-tratamiento');
    if (tratInput) {
        tratInput.addEventListener('change', (e) => {
            const file = e.target.files[0];
            const preview = document.getElementById('h-tratamiento-preview');
            if (file && preview) {
                preview.textContent = `📄 ${file.name}`;
            } else if (preview) {
                preview.textContent = '';
            }
        });
    }
}

// --- Gestión de Historial Clínico ---
const historyForm = document.getElementById('history-form');
if (historyForm) {
    historyForm.addEventListener('submit', async (e) => {
        e.preventDefault();
        const id = document.getElementById('h-id').value;

        const tratInput = document.getElementById('h-tratamiento');
        let tratamientoWordData = null;
        let tratamientoWordName = null;
        if (tratInput && tratInput.files[0]) {
            tratamientoWordName = tratInput.files[0].name;
            tratamientoWordData = await readFileAsDataURL(tratInput);
        } else if (id) {
            const allHistory = await Storage.get('history');
            const existing = allHistory.find(i => i.id == id);
            if (existing) {
                tratamientoWordData = existing.tratamientoWordData || null;
                tratamientoWordName = existing.tratamientoWordName || null;
            }
        }

        const patientId = document.getElementById('h-patient').value;
        const professionalId = document.getElementById('h-professional').value;
        const date = document.getElementById('h-date').value;
        const diagnosis = document.getElementById('h-diagnosis').value;
        const treatment = document.getElementById('h-treatment').value;
        const notes = document.getElementById('h-notes').value;

        console.log('Datos del formulario:', { patientId, professionalId, date, diagnosis, treatment, notes });

        if (!patientId || patientId === '') {
            alert('❌ Debe seleccionar un paciente');
            return;
        }
        if (!professionalId || professionalId === '') {
            alert('❌ Debe seleccionar un profesional');
            return;
        }
        if (!date) {
            alert('❌ Debe ingresar una fecha');
            return;
        }
        if (!diagnosis) {
            alert('❌ Debe ingresar un diagnóstico');
            return;
        }
        if (!treatment) {
            alert('❌ Debe ingresar un tratamiento');
            return;
        }

        const historyData = {
            patientId,
            professionalId,
            date,
            diagnosis,
            treatment,
            notes,
            tratamientoWordData,
            tratamientoWordName
        };

        try {
            if (id) {
                historyData.id = parseInt(id);
                await Storage.update('history', historyData);
                alert('✅ Historial actualizado');
            } else {
                await Storage.add('history', historyData);
                alert('✅ Historial guardado');
            }
        } catch (err) {
            console.error('Error al guardar historial:', err);
            if (err.message === 'STORAGE_FULL') {
                alert('❌ MEMORIA LLENA: No se pueden guardar más historiales.\n\nEl almacenamiento del navegador está lleno. Por favor:\n1. Ve a "Configuración" y exporta tus datos (JSON o Excel)\n2. Borra historiales antiguos que ya no necesites\n3. Luego intenta guardar nuevamente');
            } else {
                alert('❌ Error al guardar historial: ' + err.message);
            }
            return;
        }

        closeModal('history-modal');
        historyForm.reset();
        const tratPreview = document.getElementById('h-tratamiento-preview');
        if (tratPreview) tratPreview.textContent = '';
        await searchHistory();
        await loadDashboard();
    });
}

async function _setHistoryPatient(patientId) {
    const patients = await Storage.get('patients');
    const patient = patients.find(p => p.id == patientId);
    const selPt = document.getElementById('h-patient');
    if (!selPt) return;
    if (patient) {
        const phoneLabel = patient.phone ? ` - ${patient.phone}` : '';
        const label = `${patient.name} ${patient.lastname}${phoneLabel}`.trim();
        if (!Array.from(selPt.options).some(o => o.value == patient.id)) {
            selPt.innerHTML += `<option value="${patient.id}">${label}</option>`;
        }
        selPt.value = patient.id;
        const searchInput = document.getElementById('h-patient-search');
        if (searchInput) searchInput.value = label;
        const results = document.getElementById('h-patient-results');
        if (results) { results.innerHTML = ''; results.style.display = 'none'; }
    } else {
        // Paciente inexistente: se conserva igual para no perder el registro
        if (!Array.from(selPt.options).some(o => o.value == patientId)) {
            selPt.innerHTML += `<option value="${patientId}">(Paciente eliminado)</option>`;
        }
        selPt.value = patientId;
        const searchPt = document.getElementById('h-patient-search');
        if (searchPt) searchPt.value = '';
    }
}

async function _setHistoryProfessional(professionalId) {
    const doctors = await Storage.get('doctors');
    const doctor = doctors.find(d => d.id == professionalId);
    const selDr = document.getElementById('h-professional');
    if (!selDr) return;
    if (doctor) {
        const specialty = doctor.specialty ? ` - ${doctor.specialty}` : '';
        const label = `${doctor.name} ${doctor.lastname}${specialty}`.trim();
        if (!Array.from(selDr.options).some(o => o.value == doctor.id)) {
            selDr.innerHTML += `<option value="${doctor.id}">${label}</option>`;
        }
        selDr.value = doctor.id;
        const searchInput = document.getElementById('h-professional-search');
        if (searchInput) searchInput.value = label;
        const results = document.getElementById('h-professional-results');
        if (results) { results.innerHTML = ''; results.style.display = 'none'; }
    } else {
        // Profesional inexistente: se conserva igual para no perder el registro
        if (professionalId && !Array.from(selDr.options).some(o => o.value == professionalId)) {
            selDr.innerHTML += `<option value="${professionalId}">(Profesional eliminado)</option>`;
        }
        if (professionalId) selDr.value = professionalId;
        const searchDr = document.getElementById('h-professional-search');
        if (searchDr) searchDr.value = '';
        const resDr = document.getElementById('h-professional-results');
        if (resDr) { resDr.innerHTML = ''; resDr.style.display = 'none'; }
    }
}

window.editHistory = async function (id) {
    const allHistory = await Storage.get('history');
    const h = allHistory.find(item => item.id == id);
    if (!h) return;

    // Abrir el modal primero: populateSelects() reconstruye los selectores
    // y, si se hacía después de cargar los datos, borraba la selección.
    await openModal('history-modal');

    const title = document.getElementById('history-modal-title');
    if (title) title.textContent = 'Editar Historial';

    document.getElementById('h-id').value = h.id;
    document.getElementById('h-date').value = h.date;
    document.getElementById('h-diagnosis').value = h.diagnosis;
    document.getElementById('h-treatment').value = h.treatment;
    document.getElementById('h-notes').value = h.notes || '';

    // Usar la función _setHistoryPatient para asegurar que el paciente esté en el select
    await _setHistoryPatient(h.patientId);

    // Usar la función _setHistoryProfessional para asegurar que el profesional esté en el select
    if (h.professionalId) {
        await _setHistoryProfessional(h.professionalId);
    } else {
        const selDr = document.getElementById('h-professional');
        if (selDr) selDr.value = '';
        const searchDr = document.getElementById('h-professional-search');
        if (searchDr) searchDr.value = '';
        const resDr = document.getElementById('h-professional-results');
        if (resDr) { resDr.innerHTML = ''; resDr.style.display = 'none'; }
    }

    const tratPreview = document.getElementById('h-tratamiento-preview');
    if (tratPreview) {
        tratPreview.textContent = h.tratamientoWordName ? `📄 ${h.tratamientoWordName}` : '';
    }
};

window._sortHistoryByDate = function (list, order) {
    const sorted = list.slice();
    const dir = order === 'asc' ? 1 : -1;
    sorted.sort(function (a, b) {
        const da = (a.date || '').toString();
        const db = (b.date || '').toString();
        if (da < db) return -1 * dir;
        if (da > db) return 1 * dir;
        return 0;
    });
    return sorted;
};

window.searchHistory = async function () {
    const q = document.getElementById('history-search').value.toLowerCase().trim();
    const orderSelect = document.getElementById('history-order');
    const order = orderSelect ? orderSelect.value : 'desc';
    const patients = await Storage.get('patients');
    const doctors = await Storage.get('doctors');

    let allHistory = await Storage.get('history');
    let history = q ? allHistory.filter(h => {
        const p = patients.find(pat => pat.id == h.patientId) || { name: '', lastname: '' };
        const fullName = `${p.name} ${p.lastname}`.toLowerCase();
        return h.patientId == q || fullName.includes(q);
    }) : allHistory;

    history = window._sortHistoryByDate(history, order);

    const tbody = document.getElementById('history-table-body');
    if (!tbody) return;
    tbody.innerHTML = '';

    history.forEach(h => {
        const p = patients.find(pat => pat.id == h.patientId) || { name: 'Desconocido', lastname: '' };
        const d = doctors.find(doc => doc.id == h.professionalId) || { name: 'Sin asignar', lastname: '' };
        const tratLink = adjuntoIcon('history', h.id, h.tratamientoWordName, 'tratamientoWordData');
        tbody.innerHTML += `
            <tr>
                <td>${h.date}</td>
                <td>${p.name} ${p.lastname}</td>
                <td>${d.name} ${d.lastname}</td>
                <td>${h.diagnosis.substring(0, 20)}...</td>
                <td>${h.treatment.substring(0, 20)}...</td>
                <td>${h.notes ? h.notes.substring(0, 15) + '...' : ''}</td>
                <td>
                    ${tratLink}
                    <button class="btn-secondary" onclick="editHistory(${h.id})" style="padding:5px 8px; font-size:11px;"><i class='bx bxs-edit'></i></button>
                    <button class="btn-secondary" onclick="deleteHistory(${h.id})" style="background:#e74c3c; padding:5px 8px; font-size:11px;"><i class='bx bxs-trash'></i></button>
                </td>
            </tr>
        `;
    });
};

window.deleteHistory = async function (id) {
    if (confirm('¿Eliminar registro?')) {
        await Storage.delete('history', id);
        await searchHistory();
        await loadDashboard();
    }
};

window.deleteAllHistory = async function () {
    if (confirm('⚠️ ¿Está seguro de que desea borrar TODO el historial clínico?\n\nEsta acción no se puede deshacer.\n\nSi todavía no descargaste el respaldo JSON, cancelá y hacelo primero.')) {
        await Storage.set('history', []);
        await searchHistory();
        await loadDashboard();
        alert('Historial borrado completamente.');
    }
};



// --- Buscador de Pacientes para Historial ---
function _renderHistoryPatientResults(patients) {
    const results = document.getElementById('h-patient-results');
    if (!results) return;

    if (!patients || patients.length === 0) {
        results.innerHTML = '';
        results.style.display = 'none';
        return;
    }

    const max = 8;
    const items = patients.slice(0, max);
    results.innerHTML = items.map(p => {
        const phone = p.phone ? ` - ${_escapeHtml(p.phone)}` : '';
        const label = `${_escapeHtml(p.name || '')} ${_escapeHtml(p.lastname || '')}${phone}`.trim();
        return `<div class="select-result-item" onclick="selectHistoryPatient('${_escapeHtml(p.id)}')">${label}</div>`;
    }).join('');
    results.style.display = 'block';
}

window.selectHistoryPatient = function (id) {
    const sel = document.getElementById('h-patient');
    if (sel) sel.value = id;
    const results = document.getElementById('h-patient-results');
    if (results) { results.innerHTML = ''; results.style.display = 'none'; }
};

window.filterHistoryPatients = async function () {
    const input = document.getElementById('h-patient-search');
    const select = document.getElementById('h-patient');
    if (!select) return;

    const currentValue = select.value;
    const q = (input ? input.value : '').trim().toLowerCase();

    const patients = await Storage.get('patients');
    const filtered = q
        ? patients.filter(p =>
            (p.name && p.name.toLowerCase().includes(q)) ||
            (p.lastname && p.lastname.toLowerCase().includes(q)) ||
            (p.phone && p.phone.toLowerCase().includes(q))
        )
        : patients;

    _renderHistoryPatientResults(q ? filtered : []);

    select.innerHTML = '<option value="">Seleccione Paciente</option>';
    filtered.forEach(p => {
        const phoneLabel = p.phone ? ` - ${p.phone}` : '';
        select.innerHTML += `<option value="${p.id}">${p.name} ${p.lastname}${phoneLabel}</option>`;
    });

    // Siempre incluir el paciente seleccionado actualmente, aunque no coincida con el filtro
    if (currentValue && !Array.from(select.options).some(o => o.value === currentValue)) {
        const selectedPatient = patients.find(p => p.id == currentValue);
        if (selectedPatient) {
            const phoneLabel = selectedPatient.phone ? ` - ${selectedPatient.phone}` : '';
            select.innerHTML += `<option value="${selectedPatient.id}">${selectedPatient.name} ${selectedPatient.lastname}${phoneLabel}</option>`;
            select.value = currentValue;
        }
    } else if (currentValue) {
        select.value = currentValue;
    }
};

