// --- Export/Import ---
window.exportClinicData = async function () {
    const data = {
        patients: await Storage.get('patients'),
        doctors: await Storage.get('doctors'),
        appointments: await Storage.get('appointments'),
        history: await Storage.get('history'),
        exportDate: new Date().toISOString(),
        version: 'ClinicaWeb Standard v1.0'
    };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `clinica_standard_backup_${new Date().toISOString().slice(0, 10)}.json`;
    a.click();
    URL.revokeObjectURL(url);
    alert('✅ Copia de seguridad descargada correctamente');
};

window.importClinicData = async function (event) {
    const file = event.target.files[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = async function (e) {
        try {
            const data = JSON.parse(e.target.result);

            if (confirm('⚠️ ATENCIÓN: Esta acción reemplazará TODOS los datos actuales con los del archivo de respaldo. ¿Desea continuar?')) {
                if (data.patients) await Storage.set('patients', data.patients);
                if (data.doctors) await Storage.set('doctors', data.doctors);
                if (data.appointments) await Storage.set('appointments', data.appointments);
                if (data.history) await Storage.set('history', data.history);

                alert('✅ Datos importados correctamente. La página se recargará.');
                location.reload();
            }
        } catch (error) {
            alert('❌ Error al leer el archivo. Asegúrate de que es un archivo de respaldo válido.');
            console.error(error);
        }
    };
    reader.readAsText(file);
};

