// --- Excel Export/Import ---
// Excel no admite mas de 32.767 caracteres por celda. Los archivos adjuntos
// (documentacion clinica / plan de tratamiento) se guardan como data URLs base64
// dentro de localStorage y pueden pesar cientos de KB cada uno, por eso se excluyen
// del Excel y solo se conserva el nombre del archivo.
const EXCEL_CELL_MAX = 32767;
const EXCEL_CAMPOS_BINARIOS = ['tratamientoWordData', 'documentacionData'];
const EXCEL_CAMPOS_NOMBRE_ARCHIVO = ['tratamientoWordName', 'documentacionName'];
const EXCEL_CAMPOS_NUMERICOS = ['id', 'patientId', 'professionalId'];
const EXCEL_NOMBRE_ARCHIVO = {
    tratamientoWordData: 'Plan de Tratamiento (archivo)',
    documentacionData: 'Documentacion (archivo)'
};

function _excelSafeRows(rows) {
    return (rows || []).map(row => {
        const out = {};
        Object.keys(row || {}).forEach(key => {
            if (EXCEL_CAMPOS_BINARIOS.includes(key) || EXCEL_CAMPOS_NOMBRE_ARCHIVO.includes(key)) return;
            const raw = row[key];
            if (raw === null || raw === undefined || raw === '') {
                out[key] = '';
                return;
            }
            let value = raw;
            if (typeof value === 'object') value = JSON.stringify(value);
            if (EXCEL_CAMPOS_NUMERICOS.includes(key) && /^\d+$/.test(String(value))) {
                out[key] = Number(value);
                return;
            }
            value = String(value).replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g, '');
            if (value.length > EXCEL_CELL_MAX) {
                value = value.slice(0, EXCEL_CELL_MAX - 20) + '... [truncado]';
            }
            out[key] = value;
        });
        EXCEL_CAMPOS_BINARIOS.forEach(campo => {
            const nombre = row ? row[campo.replace('Data', 'Name')] : null;
            if (!row || (!row[campo] && !nombre)) return;
            out[EXCEL_NOMBRE_ARCHIVO[campo]] = nombre || 'archivo adjunto';
        });
        return out;
    });
}

function _excelAddSheet(wb, rows, sheetName, columns) {
    const data = _excelSafeRows(rows);
    const ws = XLSX.utils.json_to_sheet(data, { header: columns });
    ws['!cols'] = columns.map(() => ({ wch: 22 }));
    XLSX.utils.book_append_sheet(wb, ws, sheetName);
}

function _excelDownload(wb, filename) {
    const out = XLSX.write(wb, { bookType: 'xlsx', type: 'array' });
    const blob = new Blob([out], { type: 'application/octet-stream' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    a.rel = 'noopener';
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    setTimeout(() => URL.revokeObjectURL(url), 2000);
}

window.exportToExcel = async function () {
    try {
        if (typeof XLSX === 'undefined' || !XLSX.utils) {
            console.error('XLSX no disponible');
            alert('❌ No se pudo cargar la librería de Excel. Revisa tu conexión a internet y recarga la página.');
            return;
        }

        const patients = await Storage.get('patients');
        const doctors = await Storage.get('doctors');
        const appointments = await Storage.get('appointments');
        const allHistory = await Storage.get('history');
        const history = window._sortHistoryByDate(allHistory, 'desc');

        const wb = XLSX.utils.book_new();

        _excelAddSheet(wb, patients, 'Pacientes', ['id', 'name', 'lastname', 'dob', 'phone', 'email', 'Documentacion (archivo)']);
        _excelAddSheet(wb, doctors, 'Profesionales', ['id', 'name', 'lastname', 'specialty']);
        _excelAddSheet(wb, appointments, 'Turnos', ['id', 'patientId', 'date', 'time', 'status', 'notes']);
        _excelAddSheet(wb, history, 'Historial', ['id', 'patientId', 'professionalId', 'date', 'diagnosis', 'treatment', 'notes', 'Plan de Tratamiento (archivo)']);

        const stamp = new Date().toISOString().slice(0, 10);
        _excelDownload(wb, `LograrES_Respaldo_${stamp}.xlsx`);

        const total = patients.length + doctors.length + appointments.length + history.length;
        alert(`✅ Datos exportados a Excel correctamente\n\nPacientes: ${patients.length}\nProfesionales: ${doctors.length}\nTurnos: ${appointments.length}\nHistorial: ${history.length}\n\nTotal: ${total} registros`);
    } catch (error) {
        console.error("Error al exportar a Excel:", error);
        alert('❌ Error al exportar a Excel.\n\nDetalle: ' + (error && error.message ? error.message : String(error)));
    }
};

window.importFromExcel = function (event) {
    const input = event.target;
    const file = input.files[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = async function (e) {
        try {
            if (typeof XLSX === 'undefined' || !XLSX.utils) {
                alert('❌ No se pudo cargar la librería de Excel. Revisa tu conexión a internet y recarga la página.');
                return;
            }

            const data = new Uint8Array(e.target.result);
            const workbook = XLSX.read(data, { type: 'array' });

            const leerHoja = (nombre) => {
                if (!workbook.SheetNames.includes(nombre)) return null;
                const filas = XLSX.utils.sheet_to_json(workbook.Sheets[nombre], { defval: '' });
                return Array.isArray(filas) ? filas : null;
            };

            const patients = leerHoja('Pacientes');
            const doctors = leerHoja('Profesionales');
            const appointments = leerHoja('Turnos');
            const history = leerHoja('Historial');

            if (!patients && !doctors && !appointments && !history) {
                alert('❌ El archivo no contiene las pestañas esperadas (Pacientes, Profesionales, Turnos, Historial).');
                return;
            }

            const resumen = [];
            if (patients) resumen.push(`Pacientes: ${patients.length}`);
            if (doctors) resumen.push(`Profesionales: ${doctors.length}`);
            if (appointments) resumen.push(`Turnos: ${appointments.length}`);
            if (history) resumen.push(`Historial: ${history.length}`);

            const aviso = '\n\nNota: los archivos adjuntos (documentacion clinica y planes de tratamiento en Word) no pueden guardarse dentro de Excel, por lo que no se importaran.';

            if (confirm('⚠️ ATENCIÓN: Esta acción reemplazará TODOS los datos actuales con los del archivo Excel.\n\n' + resumen.join('\n') + aviso + '\n\n¿Desea continuar?')) {
                if (patients) await Storage.set('patients', patients);
                if (doctors) await Storage.set('doctors', doctors);
                if (appointments) await Storage.set('appointments', appointments);
                if (history) await Storage.set('history', history);

                alert('✅ Datos importados correctamente desde Excel. La página se recargará.');
                location.reload();
            }
        } catch (error) {
            alert('❌ Error al leer el archivo Excel. Asegúrate de que es un archivo .xlsx válido.\n\nDetalle: ' + (error && error.message ? error.message : String(error)));
            console.error(error);
        }
    };
    reader.readAsArrayBuffer(file);
    input.value = '';
};
